import sys

class TrieNode:
    __slots__ = ['children', 'words']
    def __init__(self):
        self.children = {}
        self.words = []

def main():
    data = sys.stdin.read().splitlines()
    if not data:
        return

    idx = 0
    N = int(data[idx])
    idx += 1

    words = []
    for _ in range(N):
        words.append(data[idx])
        idx += 1

    root = TrieNode()

    # Build the trie with reversed words
    for word in words:
        rev_word = word[::-1]
        node = root
        for char in rev_word:
            if char not in node.children:
                node.children[char] = TrieNode()
            node = node.children[char]
            node.words.append(word)

    Q = int(data[idx])
    idx += 1

    results = []
    for _ in range(Q):
        s = data[idx]
        idx += 1

        rev_s = s[::-1]
        node = root

        found = True
        for char in rev_s:
            if char not in node.children:
                found = False
                break
            node = node.children[char]

        if found and node.words:
            # Find lexicographically smallest string in node.words
            result = min(node.words)
            results.append(result)
        else:
            results.append(s)

    for r in results:
        print(r)

if __name__ == "__main__":
    main()
